{
  "category_edits": [
    {
      "category": "embedding_representation",
      "rationale": "Apply parameter-free LayerNorm to nonpadding input item embeddings before dropout and the GRU across all four datasets. Candidate embeddings, scoring, GRU topology, loss, and optimizer remain fixed. The generated predictor imports this same model class, so inference uses the identical normalization without checkpoint changes.",
      "edits": [
        {
          "find": "    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def input_embeddings(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.item_emb(seq)\n        emb = torch.nn.functional.layer_norm(emb, (self.hidden_units,))\n        emb = emb * seq.ne(0).unsqueeze(-1).to(emb.dtype)\n        return self.dropout(emb)\n\n    def encode(self, seq: torch.Tensor) -> torch.Tensor:\n        emb = self.input_embeddings(seq)"
        },
        {
          "find": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.dropout(self.item_emb(seq))",
          "replace": "    def forward(self, seq: torch.Tensor, pos: torch.Tensor, neg: torch.Tensor):\n        emb = self.input_embeddings(seq)"
        }
      ]
    }
  ],
  "change_summary": "Normalize recurrent input embeddings with parameter-free LayerNorm while preserving zero padding and consistent training/inference behavior."
}
